import numpy as np, time
from scipy import stats
segs=['S1','S2','S3','S4','S5','S6']
PD=np.array([0.02,0.05,0.12,0.30,0.60,0.90])
pay=(1-PD)*1000-PD*16000
cuts=np.array([560,630,690,750,820],dtype=float)
locs={'bureau':[810.7,756.8,763.2,735.6,691.4,635.4],
 'income':[802.0,739.7,724.8,671.6,633.8,654.5],
 'bank':[736.2,729.7,681.3,568.0,588.8,586.2]}
def make_models(bureau_df=0.91,bureau_scale=50.3,bank_df=2.87,bank_scale=35.0):
    P=np.zeros((3,6,6))
    for ci,ch in enumerate(['bureau','income','bank']):
        for si,s in enumerate(segs):
            L=locs[ch][si]
            if ch=='income': cdf=lambda x,L=L: stats.norm.cdf(x,L,70.8)
            elif ch=='bank': cdf=lambda x,L=L: stats.t.cdf(x,bank_df,L,bank_scale)
            else: cdf=lambda x,L=L: stats.t.cdf(x,bureau_df,L,bureau_scale)
            F=np.array([cdf(c) for c in cuts]); F=np.concatenate([[0],F,[1]])
            p=np.diff(F); p=np.clip(p,1e-12,None); p/=p.sum()
            P[ci,si]=p
    return P

def leaf(b): return max(0.0,float(np.dot(b,pay)))

def lookahead(b,P,depth,cost=20.0):
    # returns best value achievable with up to depth checks then decide
    if depth==0:
        return leaf(b)
    best=leaf(b)
    for ci in range(3):
        ev=-cost
        for bi in range(6):
            lik=P[ci,:,bi]; pb=float(np.dot(b,lik))
            if pb<1e-10: continue
            nb=b*lik/pb
            ev+=pb*lookahead(nb,P,depth-1,cost)
        if ev>best: best=ev
    return best

def best_action(b,P,depth,cost=20.0):
    base=leaf(b)
    best=base; act=('approve' if np.dot(b,pay)>0 else 'decline')
    for ci in range(3):
        ev=-cost
        for bi in range(6):
            lik=P[ci,:,bi]; pb=float(np.dot(b,lik))
            if pb<1e-10: continue
            nb=b*lik/pb
            ev+=pb*lookahead(nb,P,depth-1,cost)
        if ev>best+1e-9: best=ev; act=('check',ci)
    return best,act

if __name__=='__main__':
