            if ch=='income': cdf=lambda x,L=L: stats.norm.cdf(x,L,70.8)
            elif ch=='bank': cdf=lambda x,L=L: stats.t.cdf(x,bank_df,L,bank_scale)
            else: cdf=lambda x,L=L: stats.t.cdf(x,bureau_df,L,bureau_scale)
            F=np.array([cdf(c) for c in cuts]); F=np.concatenate([[0],F,[1]])
            p=np.diff(F); p=np.clip(p,1e-12,None); p/=p.sum()
            P[ci,si]=p
    return P

def lookahead(b,P,depth,cost=20.0):
    if depth==0: return max(0.0,float(np.dot(b,pay)))
    best=leaf=max(0.0,float(np.dot(b,pay)))
    for ci in range(3):
        ev=-cost
        for bi in range(6):
            lik=P[ci,:,bi]; pb=float(np.dot(b,lik))
            if pb<1e-10: continue
            nb=b*lik/pb
            ev+=pb*lookahead(nb,P,depth-1,cost)
        if ev>best: best=ev
    return best

def best_action(b,P,depth,cost=20.0):
    base=max(0.0,float(np.dot(b,pay)))
